/* The playable management sim. All money and outcomes here are fictional game rules. */
(()=>{'use strict';const C=window.AceSimCore,$=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rehearsal=null,rehearsalSnapshot=null;
let connectionLabel=window.GILDED_HOST_ENDPOINT?'Powered by Gemini':'Offline guide';let future=null,futureSnapshot=null;
let helpStyle='simple';try{helpStyle=localStorage.getItem('ace-help-style')==='numbers'?'numbers':'simple';}catch{}
let s;try{s=JSON.parse(localStorage.getItem('ace-tycoon-v1'));}catch{}if(!C.valid(s))s=C.fresh();let selected=1,zone=0,running=false,progress=0,speed=1,response='host',timer,chatBusy=false,previewRows=[],previewDay=null,chat=[{who:'host',text:s.day>1?'Welcome back, boss. Ready for night '+s.day+'? Test tonight with me, or set up tonight and open the doors.':'Welcome, boss. Pick your drinks and crew, then open the doors. I’m Ace—ask me if you get stuck.'}];
const host=document.createElement('section');host.id='simulator';host.className='sim-wrap';host.tabIndex=-1;host.setAttribute('aria-label','Casino manager simulator');document.querySelector('main').append(host);
function save(){rehearsal=null;rehearsalSnapshot=null;future=null;futureSnapshot=null;previewRows=[];previewDay=null;try{localStorage.setItem('ace-tycoon-v1',JSON.stringify(s));}catch{notice('Your browser could not save this run. Keep this tab open.');}}
function notice(t){$('simNotice').textContent=t;}
function tip(){const c=window.AceCoach.context(s,helpStyle);return helpStyle==='numbers'?c.reason+' '+c.tip:c.tip;}
function machineArt(m){return `<span class="cabinet-art level-${m.l}" aria-hidden="true"><i>♠ ♦ ♣</i><b>♠ ♦ ♣</b><em></em><small>LEVEL ${m.l}</small></span>`;}
function floor(){return C.zones.map((name,z)=>{const machines=s.machines.filter(m=>m.z===z);return `<section class="sim-zone ${C.forecast(s).zone===z?'hot-zone':''}"><div class="zone-heading"><span>${['♦','♥','♣'][z]} ${name}</span><small>${C.forecast(s).zone===z?'Tonight’s hot spot':machines.length+'/4 spaces'}</small></div><div class="zone-machines">${machines.map(m=>`<button class="sim-machine ${selected===m.id?'selected':''} ${m.wear>=95?'broken':''}" data-machine-sim="${m.id}" aria-label="Machine ${m.id}, level ${m.l}, condition ${Math.round(100-m.wear)} percent">${machineArt(m)}<span class="condition"><i style="width:${100-m.wear}%"></i></span><small>${m.wear>=95?'Needs repair':Math.round(100-m.wear)+'% condition'}</small></button>`).join('')}${Array.from({length:4-machines.length},()=>`<button class="empty-space" data-buy-zone="${z}" aria-label="Buy a machine in ${name} for ${money(C.cost(s,'buy'))}" ${s.cash<C.cost(s,'buy')||running?'disabled':''}><b>＋</b><span>Add machine</span><small>${money(C.cost(s,'buy'))}</small></button>`).join('')}</div><div class="guest-lane" aria-hidden="true">${Array.from({length:6},(_,i)=>`<span class="sim-guest" style="--i:${i};--c:${['#e9bd75','#d0a9ee','#80d7c2','#e39a9f','#a4c8ec','#f1dca6'][i]}"><i></i></span>`).join('')}</div></section>`;}).join('');}
function options(list,key){return list.map((x,i)=>`<button data-setting="${key}" data-value="${i}" aria-pressed="${s[key]===i}" ${running?'disabled':''}><b>${x.name}</b><small>${key==='menu'?money(x.price)+' drinks':key==='crew'?money(x.cost)+' / night':x.detail}</small></button>`).join('');}
function comparisonId(q){const id=Number(q.match(/machine\s+(\d+)/i)?.[1]);return s.machines.some(m=>m.id===id)?id:selected;}
function futurePanel(){if(!future)return '';return `<section class="ace-futures" aria-label="Ace’s Two Futures"><span class="sim-eyebrow">ACE’S TWO FUTURES · NIGHT ${future.night}</span><h3>Fix what you have—or make room for more?</h3><p>Machine ${future.machine_id}. Compare both choices with keeping your cash.</p><div class="future-options">${future.rows.map((r,i)=>`<article><b>${esc(r.label)}</b>${r.unavailable?`<p>${esc(r.unavailable)}</p>`:`<dl><dt>Spend now</dt><dd>${money(r.result.upfront_cost)}</dd><dt>Night profit after that cost</dt><dd>${money(r.result.net_after_upfront_cost)}</dd><dt>Difference vs keeping cash</dt><dd>${r.difference>=0?'+':''}${money(r.difference)}</dd><dt>Guests served</dt><dd>${r.result.guests_served}</dd></dl><button data-future-pick="${i}" ${running?'disabled':''}>${i===0?'Keep my cash':i===1?'Choose repair':'Choose new machine'}</button>`}</article>`).join('')}</div><details><summary>What could change this?</summary><p>${esc(future.assumption)} Upfront costs count once; milestone bonuses and later nights are excluded. A purchase may help over several nights even if it loses on night one.</p><p>${esc(future.placement)}</p></details></section>`;}

function rehearsalPanel(){if(!rehearsal)return '';const base=rehearsal.rows[0],best=rehearsal.rows.find(r=>r.id===(rehearsal.pickId||rehearsal.bestId)),shown=best.id==='keep'?[base]:[base,best];return `<section class="ace-futures ace-rehearsal" tabindex="-1" aria-label="Ace’s rehearsal"><span class="sim-eyebrow">ACE’S TEST RUN · NIGHT ${rehearsal.night}</span><h3>Try the idea before spending.</h3><p>${rehearsal.provider==='Gemini'?'Gemini picked the ideas.':'Local fallback picked the ideas.'} The game tried ${rehearsal.samples} versions of tonight for each. ${best.id==='keep'?'Ace suggests keeping your current plan.':'Here is Ace’s pick, with the tradeoff shown below.'}</p><div class="future-options">${shown.map(r=>`<article><b>${esc(r.label)}</b><dl><dt>Spend now</dt><dd>${money(r.upfront)}</dd><dt>Average night profit after that cost</dt><dd>${money(r.averageNet)}</dd><dt>Average guest happiness</dt><dd>${Math.round(r.averageHappiness)}/100</dd></dl>${r.id!=='keep'?`<p class="rehearsal-risk">${r.worseNights?`Did worse than your current plan in ${r.worseNights} of ${r.samples} rehearsals.`:'Did not lose to your current plan in these rehearsals. It still may later.'}</p>`:''}<button data-rehearsal-pick="${esc(r.id)}" ${running||chatBusy?'disabled':''}>${r.id==='keep'?'Keep my plan':r.upfront?'Choose this · '+money(r.upfront):'Use these settings'}</button></article>`).join('')}</div><details><summary>What Ace tested & what could go wrong</summary>${rehearsal.rows.map(r=>`<p><b>${esc(r.label)}</b> — ${money(r.averageNet)} average after costs; ${money(r.lowestNet)} to ${money(r.highestNet)} across these runs. ${r.id!=='keep'?`Worst difference from your current plan: ${money(r.worstDifference)}. Average happiness change: ${r.happinessChange>=0?'+':''}${r.happinessChange.toFixed(1)}.`:''}</p>`).join('')}<p>${esc(rehearsal.assumption)}</p></details></section>`;}

function render(){const event=C.forecast(s),m=s.machines.find(m=>m.id===selected);host.innerHTML=`<div class="sim-top"><div><span class="sim-eyebrow">REELUXE · ${s.prestige?'RESORT '+(s.prestige+1):'YOUR FIRST CASINO'}</span><h1>Make tonight a big night.</h1></div><a class="sim-evidence" href="#analysis">Our Casino Findings →</a></div><p class="sim-challenge-note">Your casino, your call. <a href="#analysis">Explore our findings →</a></p><div class="sim-hud"><div><small>CASH TO BUILD</small><strong>${money(s.cash)}</strong></div><div><small>GUEST HAPPINESS</small><strong>${Math.round(s.rating)}<em>/100</em> <span>${s.rating>=75?'♥':'♡'}</span></strong></div><div><small>NIGHT</small><strong>${s.day}</strong></div><div><small>YOUR FLOOR</small><strong>${s.machines.length}<em>/12</em></strong></div></div><div id="simNotice" class="sim-notice" role="status" aria-live="polite"></div><a class="sim-mobile-jump" href="#nightSetup">Set up tonight ↓</a><div class="sim-layout"><div class="sim-main"><div class="event-strip"><span>${event.icon}</span><div><b>${event.name}</b><p>${event.text}</p></div><span class="sim-weather">${s.prestige?'+'+s.prestige*6+'% resort bonus':'Tonight’s forecast'}</span></div>${s.day===1?'<div class="sim-onboarding">Your first night: <b>1. Pick a menu</b> <b>2. Open the doors</b> <b>3. Reinvest your earnings</b><span>Start small. Grow at your own pace.</span></div>':''}<div class="sim-floor ${running?'is-open':''}" id="simFloor"><div class="floor-sign">♠ THE GILDED ACE <small>${running?'DOORS OPEN':'GETTING READY FOR TONIGHT'}</small></div><div class="sim-zones">${floor()}</div><div class="floor-carpet"><span>BAR & LOUNGE</span><i>● ● ●</i><span>WELCOME TO THE STRIP</span></div><div id="liveEarnings" class="live-earnings" aria-live="off"></div></div><div class="machine-toolbar">${m?`<div><b>Machine ${m.id} · Level ${m.l}</b><small>${C.zones[m.z]} · ${Math.round(100-m.wear)}% condition</small></div><button data-machine-action="repair" ${running||s.cash<C.cost(s,'repair',m.id)||m.wear===0?'disabled':''}>🔧 Repair ${money(C.cost(s,'repair',m.id))}</button><button data-machine-action="upgrade" ${running||m.l===3||s.cash<C.cost(s,'upgrade',m.id)?'disabled':''}>✦ ${m.l===3?'Fully upgraded':'Upgrade '+money(C.cost(s,'upgrade',m.id))}</button><label>Move to<select id="simMove" ${running?'disabled':''}><option value="">Choose area · $80</option>${C.zones.map((z,i)=>i===m.z?'':`<option value="${i}" ${s.machines.filter(m=>m.z===i).length>=4?'disabled':''}>${z}</option>`).join('')}</select></label>`:'Tap a machine to upgrade, repair or move it.'}</div>${s.last?`<section class="night-recap"><div><span>NIGHT ${s.last.day} CLOSED</span><h2>${s.last.net>=0?'A night in the green.':'Time to change the plan.'}</h2></div><strong class="${s.last.net<0?'loss':''}">${s.last.net>=0?'+':''}${money(s.last.net)}</strong><p>${s.last.served} guests served · ${s.last.missed} could not find a machine · ${s.last.broken} machine${s.last.broken===1?'':'s'} jammed</p>${s.last.rewards.map(r=>`<div class="milestone">✦ ${r.title} — ${money(r.reward)} building bonus!</div>`).join('')}<details><summary>Where did the money go?</summary><p>Machines & bar: ${money(s.last.revenue)} · Running costs: ${money(s.last.operating)} · Extra drinks: ${money(s.last.responseCost)}. Bonuses are separate from nightly profit.</p><div class="zone-recap">${s.last.zoneResults.map(z=>`<span>${C.zones[z.z]}<b>${z.served}/${z.demand} guests served</b></span>`).join('')}</div></details></section>`:''}<details class="sim-rules"><summary>How this game works</summary><p>Machines have limited space for guests. Better condition and upgrades let you serve more. Location matters: the nightly event shifts the crowd. Cheap drinks attract more visitors; expensive drinks earn more per guest. More staff costs money but protects machines and happiness. Advertising helps only if you have room.</p><p>This is an original fictional economy, not a prediction from the datathon data. No real wagers, payments or prizes. Nothing happens while you’re away. You can play as many nights as you like.</p><button id="simReset" class="quiet">Start a new casino</button></details></div><aside class="sim-sidebar"><section class="night-controls" id="nightSetup"><div class="sim-section-title"><span>SET UP TONIGHT</span><small>Quick choices, big consequences</small></div><label>Drink menu</label><div class="sim-options">${options(C.menus,'menu')}</div><label>Your crew</label><div class="sim-options">${options(C.staff,'crew')}</div><label>Spread the word</label><div class="sim-options">${options([{name:'Word of mouth',detail:'Free'},{name:'Flyers',detail:'$120 / night'},{name:'City buzz',detail:'$280 / night'}],'promo')}</div><button class="outline" data-ask="Rehearse tonight. Test a few sensible ideas for my floor before I spend." ${running||chatBusy?'disabled':''}>${chatBusy?'Ace is thinking…':'✦ Test tonight with Ace'}</button><button class="open-night" id="runNight" ${running?'disabled':''}>${running?'The floor is buzzing…':'Open for night '+s.day+' →'}</button><div class="shift-live" ${running?'':'hidden'}><div class="shift-meter"><i id="shiftProgress" style="width:${progress}%"></i></div><div class="sim-speed"><button id="simSpeed">${speed}× speed</button><button id="simFinish">Close & see results →</button></div><div class="rush-choice"><b>A rush of guests! Where do you help?</b><button data-response="host" aria-pressed="${response==='host'}">Greet guests · free</button><button data-response="tech" aria-pressed="${response==='tech'}">Help the machines · free</button><button data-response="drinks" aria-pressed="${response==='drinks'}">Complimentary drinks · $75</button></div></div>${s.cash<300?'<button class="outline" id="simRescue">Reopen smaller · free fresh start</button>':''}</section><section class="host-card"><div class="host-heading"><div class="ace-portrait"><img src="assets/ace-host.svg" alt="Ace, your casino host in a suit and glasses" width="88" height="106"></div><div><h2>Ace</h2><p>Your AI floor host</p><small id="hostMode">${connectionLabel}</small></div></div><div class="coach-style" role="group" aria-label="Ace explanation style"><button data-help-style="simple" aria-pressed="${helpStyle==='simple'}">Keep it simple</button><button data-help-style="numbers" aria-pressed="${helpStyle==='numbers'}">Show numbers</button></div><p class="host-tip">“${esc(tip())}”</p><details class="coach-why"><summary>Why this suggestion?</summary><p>${esc(window.AceCoach.context(s,helpStyle).reason)} Guidance adapts to your floor. Prices, luck and rewards stay the same.</p></details><div class="host-chat" id="hostChat" role="log" aria-label="Chat with Ace">${chat.slice(-5).map(c=>`<p class="chat-${c.who}"><b>${c.who==='user'?'You':'Ace'}</b>${esc(c.text)}</p>`).join('')}</div><div class="host-prompts"><button data-ask="Why did I lose guests?">Why did guests leave?</button><button data-ask="Repair or buy? Compare repairing my selected machine with adding a new machine and keeping cash.">Repair or buy?</button></div><form id="hostForm"><label class="sr-only" for="hostQuestion">Ask Ace</label><input id="hostQuestion" placeholder="Ask Ace…" maxlength="400" autocomplete="off"><button ${chatBusy?'disabled':''}>${chatBusy?'…':'Send'}</button></form>${!future&&previewRows.length?`<section class="ace-preview"><h3>Try before spending · night ${previewDay}</h3><p>A side-by-side look at the next fictional night. Compare the cost with what it could earn.</p>${previewRows.map(r=>`<div class="ace-option"><b>${esc(r.label||choiceLabel(r.choice))}</b><dl><dt>Spend now</dt><dd>${money(r.result.upfront_cost)}</dd><dt>Nightly profit</dt><dd>${money(r.result.nightly_profit)}</dd><dt>After this purchase</dt><dd>${money(r.result.net_after_upfront_cost)}</dd><dt>Guests served</dt><dd>${r.result.guests_served}</dd></dl></div>`).join('')}<small>Purchase costs are paid once. Future benefits and milestone bonuses are not included in these net figures. This snapshot does not buy anything.</small></section>`:''}<button type="button" class="quiet ace-privacy" data-ace-privacy>How Ace uses your data</button></section><section class="sim-goals"><h3>Your next big thing</h3>${C.goals(s).filter(g=>!s.claimed.includes(g.id)).slice(0,2).map(g=>`<div><b>${g.title}</b><span>${Math.min(g.value,g.target)} / ${g.target} · ${money(g.reward)} bonus</span><progress max="${g.target}" value="${g.value}"></progress></div>`).join('')||'<p>All milestones cleared. Keep growing—or start your next resort.</p>'}<button id="nextResort" ${s.cash<20000||running?'disabled':''}>Open another resort · $20,000</button><small>Start a new floor and earn 6% more at every resort.</small></section></aside></div>${futurePanel()}${rehearsalPanel()}`;}
function finish(){if(!running)return;running=false;clearInterval(timer);s=C.shift(s,response);save();render();notice(`Night ${s.last.day} complete. ${s.last.net>=0?'Earned':'Lost'} ${money(Math.abs(s.last.net))}.`);$('runNight').focus({preventScroll:true});}
function start(){if(running)return;running=true;progress=0;response='host';render();timer=setInterval(()=>{progress=Math.min(100,progress+2.5*speed);if($('shiftProgress'))$('shiftProgress').style.width=progress+'%';if($('liveEarnings'))$('liveEarnings').textContent=progress<35?'Guests are arriving…':progress<70?'The floor is filling up…':'Last call. Closing the books…';if(progress>=100)finish();},250);}
function choiceLabel(c={}){return c.action&&c.action!=='none'?`${c.action[0].toUpperCase()+c.action.slice(1)}${c.machine_id?' machine '+c.machine_id:' a machine'}`:'Keep current settings';}
function localReply(q){if(/what should i do next/i.test(q))return tip();if(/repair.*buy|buy.*repair/i.test(q)){future=window.AceAdvisor.futures(s,comparisonId(q));futureSnapshot=JSON.stringify(s);previewRows=[];return "Let’s peek at two possible nights. Repair restores this machine; buying adds capacity. The cards include what you pay now. A stronger next night does not prove a better long-term choice. These are local calculations, not live Gemini.";}if(/compar|option|upgrade|repair|spend/i.test(q)){const named=Number(q.match(/machine\s+(\d+)/i)?.[1]);previewRows=window.AceAdvisor.compare(s,named||selected);previewDay=s.day;return 'I checked your selected machine against keeping cash. Look below: an upgrade may serve more guests, but its upfront price can outweigh one night’s gain. These are local calculator results.';}if(/tonight/i.test(q)){const choices=C.compare(s);return 'Same fictional night, three ways to help: '+choices.map(x=>`${({host:'greet guests',tech:'help machines',drinks:'offer drinks'})[x.response]} → ${money(x.net)} profit, ${x.happiness}/100 happiness`).join('; ')+'. These are game simulations, not real casino forecasts.';}if(/guest|leave|lost|lose/i.test(q)&&s.last)return `${s.last.missed} visitors could not find room last night. ${s.last.broken?'Fix the jammed machines first.':'Look at the busiest area in your night report.'} More advertising won’t help if the floor is already full.`;if(/price|drink|menu/i.test(q))return 'Value drinks bring more guests but earn less per person. Fancy drinks earn more per guest but attract fewer. Try one menu change and compare your next night.';if(/repair|upgrade|machine/i.test(q))return tip();return tip()+' Your choices stay yours. I never buy anything for you.';}
function showComparison(){const panel=host.querySelector('.ace-futures');if(!panel)return;panel.setAttribute('tabindex','-1');panel.focus({preventScroll:true});panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
async function ask(q){q=q.trim().slice(0,400);if(!q||chatBusy)return;const isRehearsal=/rehearse|rehearsal/i.test(q);if(isRehearsal&&running){notice("Let this night finish, then rehearse the next one.");return;}const snapshot=JSON.parse(JSON.stringify(s)),selectedSnapshot=comparisonId(q);const isFutures=!isRehearsal&&/repair.*buy|buy.*repair/i.test(q);if(isRehearsal){future=null;rehearsal=null;previewRows=[];}if(isFutures){rehearsal=null;rehearsalSnapshot=null;future=window.AceAdvisor.futures(snapshot,selectedSnapshot);futureSnapshot=JSON.stringify(snapshot);previewRows=[];}chat.push({who:'user',text:q});chatBusy=true;render();try{let text,mode='Local tips';if(window.GILDED_HOST_ENDPOINT){const r=await fetch(window.GILDED_HOST_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q.slice(0,350)+` Selected machine: ${selectedSnapshot}.`,state:snapshot,detail:helpStyle,mode:isRehearsal?'rehearsal':isFutures?'futures':'game',machine_id:selectedSnapshot}),signal:AbortSignal.timeout(50000)});if(!r.ok)throw Error('Host temporarily unavailable');const data=await r.json();if(typeof data.reply!=='string')throw Error('Invalid reply');text=data.reply;mode='Gemini';if(isRehearsal){if(JSON.stringify(s)!==JSON.stringify(snapshot))throw Error('Floor changed');if(!data.rehearsal||!Array.isArray(data.rehearsal.rows))throw Error('Missing rehearsal');rehearsal=window.AceRehearsal.finalize(snapshot,data.rehearsal.rows.map(r=>r.id).filter(id=>id!=='keep'),selectedSnapshot,data.rehearsal.pickId,data.rehearsal.reason);text=window.AceRehearsal.narrate(rehearsal);rehearsal.provider='Gemini';rehearsalSnapshot=JSON.stringify(snapshot);}previewRows=(data.comparisons||[]).slice(0,4).map(r=>({choice:r.choice,result:window.AceAdvisor.preview(snapshot,r.choice)}));previewDay=snapshot.day;}else {if(isRehearsal)throw Error('Offline rehearsal');text=localReply(q);}chat.push({who:'host',text});chatBusy=false;render();if(isFutures||isRehearsal)showComparison();$('hostMode').textContent=connectionLabel=mode==='Gemini'?'Powered by Gemini':'Local tips · Gemini not connected';}catch{if(isRehearsal&&JSON.stringify(s)===JSON.stringify(snapshot)){const ideas=window.AceRehearsal.catalog(snapshot,selectedSnapshot).filter(p=>p.id==='crew-0'||p.id==='repair-'+selectedSnapshot).slice(0,2);rehearsal=window.AceRehearsal.report(snapshot,ideas.map(p=>p.id),selectedSnapshot);rehearsal.provider='Local fallback';rehearsalSnapshot=JSON.stringify(snapshot);chat.push({who:'host',text:'Gemini could not finish this rehearsal. These ideas came from local rules; the calculator still ran the comparison. You can keep your current plan.'});}else chat.push({who:'host',text:isRehearsal?'Your floor changed while Ace was thinking. Rehearse again for the current floor.':'My live connection is unavailable. Here’s a local tip: '+localReply(q)});chatBusy=false;render();if(isFutures||isRehearsal)showComparison();$('hostMode').textContent=connectionLabel='Local fallback · AI unavailable';}}
host.addEventListener('click',ev=>{if(ev.target.closest('.sim-mobile-jump')){ev.preventDefault();$('nightSetup').scrollIntoView({behavior:'smooth'});return;}const b=ev.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-ace-privacy')){$('credits').showModal();return;}if(b.dataset.rehearsalPick!==undefined){if(running||chatBusy||!rehearsal||rehearsalSnapshot!==JSON.stringify(s)){notice('Your floor changed. Rehearse again before choosing.');return;}const id=b.dataset.rehearsalPick;if(!rehearsal.rows.some(r=>r.id===id))return;if(id!=='keep')s=window.AceRehearsal.apply(s,id,rehearsal.machineId);save();render();notice(id==='keep'?'Your plan is unchanged.':'Plan chosen. Open the doors when you’re ready.');return;}if(b.dataset.futurePick!==undefined){if(running||!future||futureSnapshot!==JSON.stringify(s)){notice('Your floor changed. Ask Ace to compare again.');return;}const row=future.rows[Number(b.dataset.futurePick)];if(!row||row.unavailable)return;if(row.choice.action){s=C.action(s,row.choice.action,row.choice.machine_id,row.choice.zone);save();render();notice('Your choice is ready. Open the night to see what happens.');}else{future=null;futureSnapshot=null;render();notice('Cash kept. You can still change your mind.');}return;}if(b.dataset.helpStyle){helpStyle=b.dataset.helpStyle;try{localStorage.setItem('ace-help-style',helpStyle);}catch{}render();return;}if(b.dataset.ask){ask(b.dataset.ask);return;}if(b.id==='simSpeed'){speed=speed===1?3:1;b.textContent=speed+'× speed';return;}if(b.id==='simFinish'){finish();return;}if(b.dataset.response){response=b.dataset.response;host.querySelectorAll('[data-response]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.response===response)));return;}if(b.dataset.machineSim){selected=+b.dataset.machineSim;zone=s.machines.find(m=>m.id===selected).z;render();return;}if(running)return;if(b.dataset.setting){s[b.dataset.setting]=+b.dataset.value;save();render();return;}if(b.dataset.buyZone!==undefined){zone=+b.dataset.buyZone;s=C.action(s,'buy',null,zone);selected=s.nextId-1;save();render();notice('New machine installed. Ready for tonight.');return;}if(b.dataset.machineAction){s=C.action(s,b.dataset.machineAction,selected);save();render();notice('Machine ready.');return;}if(b.id==='runNight')start();if(b.id==='nextResort'&&confirm('Open a new resort? Your current floor resets; you gain a permanent earnings bonus.')){s=C.nextResort(s);selected=1;save();render();}if(b.id==='simRescue'){s=C.rescue(s);selected=s.machines[0].id;save();render();}if(b.id==='simReset'&&confirm('Start over? This replaces only your simulator save.')){s=C.fresh();selected=1;save();render();}}catch(e){notice(e.message);}});
host.addEventListener('change',e=>{if(e.target.id==='simMove'&&e.target.value!==''&&!running){try{s=C.action(s,'move',selected,+e.target.value);save();render();notice('Machine moved. Watch that area next shift.');}catch(x){notice(x.message);}}});host.addEventListener('submit',e=>{if(e.target.id==='hostForm'){e.preventDefault();ask($('hostQuestion').value);}});
window.AceSim={reset:()=>{s=C.fresh();selected=1;render();},enter:()=>{render();host.focus({preventScroll:true});},getState:()=>cloneState(),pause:()=>{if(running)finish();}};function cloneState(){return JSON.parse(JSON.stringify(s));}render();
})();
